import java.util.Scanner

fun getDay(s: String): Int {
    if (s.isEmpty()) return 0
    val c0 = s[0]
    if (c0 == 'm') return 1
    if (c0 == 't') {
        if (s.length > 1 && s[1] == 'u') return 2
        if (s.length > 1 && s[1] == 'h') return 4
    }
    if (c0 == 'w') return 3
    if (c0 == 'f') return 5
    if (c0 == 's') {
        if (s.length > 1 && s[1] == 'a') return 6
        if (s.length > 1 && s[1] == 'u') return 7
    }
    return 0
}

